//! Paired statistics over per-query metric values.
//!
//! Every routine here is checked against SciPy, NumPy or statsmodels on fixed
//! fixtures (`tests/stats_parity.rs`, generated by `parity/stats.py`).

use crate::rng::Xoshiro256pp;

pub fn mean(xs: &[f64]) -> f64 {
    xs.iter().sum::<f64>() / xs.len() as f64
}

/// Sample standard deviation (denominator n - 1). NaN when n < 2.
pub fn sample_sd(xs: &[f64]) -> f64 {
    let n = xs.len();
    if n < 2 {
        return f64::NAN;
    }
    let m = mean(xs);
    let ss: f64 = xs.iter().map(|x| (x - m) * (x - m)).sum();
    (ss / (n - 1) as f64).sqrt()
}

/// Result of a two-sided paired t-test, as `scipy.stats.ttest_rel` reports it.
#[derive(Clone, Copy, Debug)]
pub struct TTest {
    pub t: f64,
    pub df: f64,
    pub p: f64,
}

/// Paired t-test on differences `d = b - a`: `t = mean(d) / (sd(d) / sqrt(n))`
/// with `n - 1` degrees of freedom and a two-sided p-value. With zero variance
/// the statistic is ±inf (p = 0) when the mean is non-zero and NaN when it is
/// zero, as in SciPy; with fewer than two pairs both are NaN.
pub fn paired_t(d: &[f64]) -> TTest {
    let n = d.len();
    if n < 2 {
        return TTest {
            t: f64::NAN,
            df: f64::NAN,
            p: f64::NAN,
        };
    }
    let df = (n - 1) as f64;
    let m = mean(d);
    let sd = sample_sd(d);
    let t = m / (sd / (n as f64).sqrt());
    let p = if t.is_nan() {
        f64::NAN
    } else if t.is_infinite() {
        0.0
    } else {
        student_t_two_sided(t, df)
    };
    TTest { t, df, p }
}

/// Two-sided tail probability `P(|T| >= |t|)` for Student's t with `df`
/// degrees of freedom: the regularized incomplete beta `I_x(df/2, 1/2)` with
/// `x = df / (df + t^2)`.
pub fn student_t_two_sided(t: f64, df: f64) -> f64 {
    let t2 = t * t;
    let x = df / (df + t2);
    let one_minus_x = t2 / (df + t2);
    reg_inc_beta(df / 2.0, 0.5, x, one_minus_x)
}

/// Natural log of the gamma function for `x > 0` (Lanczos approximation,
/// g = 7, nine coefficients; relative error near 1e-15).
pub fn ln_gamma(x: f64) -> f64 {
    const G: f64 = 7.0;
    const C: [f64; 9] = [
        0.999_999_999_999_809_9,
        676.520_368_121_885_1,
        -1_259.139_216_722_402_8,
        771.323_428_777_653_1,
        -176.615_029_162_140_6,
        12.507_343_278_686_905,
        -0.138_571_095_265_720_12,
        9.984_369_578_019_572e-6,
        1.505_632_735_149_311_6e-7,
    ];
    if x < 0.5 {
        // Reflection: Γ(x)Γ(1-x) = π / sin(πx).
        let pi = std::f64::consts::PI;
        return (pi / (pi * x).sin()).ln() - ln_gamma(1.0 - x);
    }
    let x = x - 1.0;
    let mut a = C[0];
    let t = x + G + 0.5;
    for (i, c) in C.iter().enumerate().skip(1) {
        a += c / (x + i as f64);
    }
    0.5 * (2.0 * std::f64::consts::PI).ln() + (x + 0.5) * t.ln() - t + a.ln()
}

/// Regularized incomplete beta `I_x(a, b)`, given both `x` and `1 - x` so the
/// caller can supply `1 - x` without cancellation. Continued fraction by the
/// modified Lentz method (Numerical Recipes, `betai`/`betacf`).
pub fn reg_inc_beta(a: f64, b: f64, x: f64, one_minus_x: f64) -> f64 {
    if x <= 0.0 {
        return 0.0;
    }
    if one_minus_x <= 0.0 {
        return 1.0;
    }
    let ln_front = ln_gamma(a + b) - ln_gamma(a) - ln_gamma(b) + a * x.ln() + b * one_minus_x.ln();
    if x < (a + 1.0) / (a + b + 2.0) {
        ln_front.exp() * beta_cf(a, b, x) / a
    } else {
        1.0 - ln_front.exp() * beta_cf(b, a, one_minus_x) / b
    }
}

fn beta_cf(a: f64, b: f64, x: f64) -> f64 {
    const TINY: f64 = 1e-300;
    const EPS: f64 = 1e-16;
    let qab = a + b;
    let qap = a + 1.0;
    let qam = a - 1.0;
    let mut c = 1.0;
    let mut d = 1.0 - qab * x / qap;
    if d.abs() < TINY {
        d = TINY;
    }
    d = 1.0 / d;
    let mut h = d;
    for m in 1..=100_000 {
        let m = f64::from(m);
        let m2 = 2.0 * m;
        let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
        d = 1.0 + aa * d;
        if d.abs() < TINY {
            d = TINY;
        }
        c = 1.0 + aa / c;
        if c.abs() < TINY {
            c = TINY;
        }
        d = 1.0 / d;
        h *= d * c;
        let aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
        d = 1.0 + aa * d;
        if d.abs() < TINY {
            d = TINY;
        }
        c = 1.0 + aa / c;
        if c.abs() < TINY {
            c = TINY;
        }
        d = 1.0 / d;
        let del = d * c;
        h *= del;
        if (del - 1.0).abs() < EPS {
            return h;
        }
    }
    h
}

/// How a randomization p-value was obtained.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PermMethod {
    /// All 2^m sign assignments of the m non-zero differences were enumerated.
    Exact,
    /// Monte Carlo sign flips; the p-value is `(1 + hits) / (1 + trials)`.
    MonteCarlo,
}

#[derive(Clone, Copy, Debug)]
pub struct PermTest {
    pub p: f64,
    pub method: PermMethod,
    /// Sign assignments evaluated (2^m when exact).
    pub samples: u64,
}

/// Relative tolerance under which a permuted statistic counts as tying the
/// observed one; absorbs floating-point summation error.
pub const PERM_TIE_TOLERANCE: f64 = 1e-9;

/// Two-sided paired randomization (sign-flip) test of `mean(d) = 0`.
///
/// Under the null each difference is equally likely to have either sign. The
/// statistic is `S = sum(d)`; a sign assignment is at least as extreme when
/// `|S*| >= |S| - 1e-9 * sum(|d|)`. Zero differences do not change S and are
/// dropped. When `2^m <= trials` for the `m` non-zero differences every
/// assignment is enumerated and the p-value is exact; otherwise `trials`
/// assignments are drawn and `p = (1 + hits) / (1 + trials)`, which is never 0.
/// With no pairs at all the p-value is NaN, so the comparison stays out of a
/// multiple-comparison family (as the t-test's NaN does).
pub fn paired_randomization(d: &[f64], trials: u64, rng: &mut Xoshiro256pp) -> PermTest {
    if d.is_empty() {
        return PermTest {
            p: f64::NAN,
            method: PermMethod::Exact,
            samples: 0,
        };
    }
    let nz: Vec<f64> = d.iter().copied().filter(|x| *x != 0.0).collect();
    let m = nz.len();
    let observed: f64 = nz.iter().sum::<f64>().abs();
    let scale: f64 = nz.iter().map(|x| x.abs()).sum();
    let threshold = observed - PERM_TIE_TOLERANCE * scale;
    if m < 64 && (1u64 << m) <= trials.max(1) {
        let total = 1u64 << m;
        let mut hits = 0u64;
        for mask in 0..total {
            let mut s = 0.0;
            for (i, x) in nz.iter().enumerate() {
                if mask >> i & 1 == 1 {
                    s -= x;
                } else {
                    s += x;
                }
            }
            if s.abs() >= threshold {
                hits += 1;
            }
        }
        return PermTest {
            p: hits as f64 / total as f64,
            method: PermMethod::Exact,
            samples: total,
        };
    }
    let mut hits = 0u64;
    for _ in 0..trials {
        let mut s = 0.0;
        let mut bits = 0u64;
        for (i, x) in nz.iter().enumerate() {
            if i % 64 == 0 {
                bits = rng.next_u64();
            }
            if bits & 1 == 1 {
                s -= x;
            } else {
                s += x;
            }
            bits >>= 1;
        }
        if s.abs() >= threshold {
            hits += 1;
        }
    }
    PermTest {
        p: (1 + hits) as f64 / (1 + trials) as f64,
        method: PermMethod::MonteCarlo,
        samples: trials,
    }
}

/// Linear-interpolation quantile of sorted data (NumPy's default `linear`
/// method, Hyndman–Fan type 7).
pub fn quantile_sorted(sorted: &[f64], q: f64) -> f64 {
    let n = sorted.len();
    if n == 0 {
        return f64::NAN;
    }
    let h = (n - 1) as f64 * q;
    let lo = h.floor() as usize;
    let hi = (lo + 1).min(n - 1);
    let frac = h - lo as f64;
    sorted[lo] + frac * (sorted[hi] - sorted[lo])
}

/// Paired percentile bootstrap interval for `mean(d)`: `resamples` resamples
/// of the n queries with replacement, then the `(1-level)/2` and
/// `(1+level)/2` quantiles of the resampled means (type 7 interpolation).
pub fn bootstrap_mean_ci(
    d: &[f64],
    resamples: u64,
    level: f64,
    rng: &mut Xoshiro256pp,
) -> (f64, f64) {
    let n = d.len();
    if n == 0 || resamples == 0 {
        return (f64::NAN, f64::NAN);
    }
    let mut means = Vec::with_capacity(resamples as usize);
    for _ in 0..resamples {
        let mut s = 0.0;
        for _ in 0..n {
            s += d[rng.below(n as u64) as usize];
        }
        means.push(s / n as f64);
    }
    means.sort_by(f64::total_cmp);
    let alpha = 1.0 - level;
    (
        quantile_sorted(&means, alpha / 2.0),
        quantile_sorted(&means, 1.0 - alpha / 2.0),
    )
}

/// Multiple-comparison correction applied to a family of p-values. In
/// `research.toml`: `"none"`, `"holm"` or `"bh"`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Correction {
    None,
    /// Holm–Bonferroni step-down (controls the family-wise error rate).
    Holm,
    /// Benjamini–Hochberg step-up (controls the false discovery rate).
    #[serde(rename = "bh")]
    BenjaminiHochberg,
}

/// Adjusted p-values, matching `statsmodels.stats.multitest.multipletests`
/// with `holm` and `fdr_bh`. NaN entries are left out of the family and stay
/// NaN.
pub fn adjust(p: &[f64], method: Correction) -> Vec<f64> {
    let mut out = vec![f64::NAN; p.len()];
    let mut idx: Vec<usize> = (0..p.len()).filter(|&i| !p[i].is_nan()).collect();
    let m = idx.len();
    if m == 0 {
        return out;
    }
    idx.sort_by(|&a, &b| p[a].total_cmp(&p[b]).then(a.cmp(&b)));
    match method {
        Correction::None => {
            for &i in &idx {
                out[i] = p[i];
            }
        }
        Correction::Holm => {
            let mut running: f64 = 0.0;
            for (rank, &i) in idx.iter().enumerate() {
                let v = ((m - rank) as f64 * p[i]).min(1.0);
                running = running.max(v);
                out[i] = running;
            }
        }
        Correction::BenjaminiHochberg => {
            let mut running: f64 = 1.0;
            for (rank, &i) in idx.iter().enumerate().rev() {
                let v = (m as f64 / (rank + 1) as f64 * p[i]).min(1.0);
                running = running.min(v);
                out[i] = running;
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ln_gamma_known_values() {
        assert!((ln_gamma(1.0)).abs() < 1e-14);
        assert!((ln_gamma(0.5) - std::f64::consts::PI.sqrt().ln()).abs() < 1e-14);
        assert!((ln_gamma(10.0) - 362_880f64.ln()).abs() < 1e-12);
    }

    #[test]
    fn t_tail_df1_is_cauchy() {
        // P(|T| >= 1) for df = 1 is 0.5.
        assert!((student_t_two_sided(1.0, 1.0) - 0.5).abs() < 1e-14);
    }

    #[test]
    fn exact_permutation_small_case() {
        // d = [1, 2, 3]: sums over 8 sign patterns are ±6, ±4, ±2, ±0;
        // |S| >= 6 for 2 of 8.
        let mut rng = Xoshiro256pp::from_seed(1);
        let r = paired_randomization(&[1.0, 2.0, 3.0], 10_000, &mut rng);
        assert_eq!(r.method, PermMethod::Exact);
        assert!((r.p - 0.25).abs() < 1e-15);
        let r = paired_randomization(&[0.0, 0.0], 10_000, &mut rng);
        assert_eq!(r.p, 1.0);
        let r = paired_randomization(&[], 10_000, &mut rng);
        assert!(r.p.is_nan());
        assert_eq!(r.samples, 0);
    }

    #[test]
    fn holm_and_bh_small_family() {
        let p = [0.01, 0.04, 0.03, f64::NAN];
        let h = adjust(&p, Correction::Holm);
        assert!((h[0] - 0.03).abs() < 1e-15);
        assert!((h[2] - 0.06).abs() < 1e-15);
        assert!((h[1] - 0.06).abs() < 1e-15);
        assert!(h[3].is_nan());
        let b = adjust(&p, Correction::BenjaminiHochberg);
        assert!((b[0] - 0.03).abs() < 1e-15);
        assert!((b[1] - 0.04).abs() < 1e-15);
        assert!((b[2] - 0.04).abs() < 1e-15);
    }
}
